#!/usr/bin/env python3

# Generated by Claude

"""
Convert cookies copied from Chrome DevTools (Application > Storage > Cookies,
select all rows, Ctrl+C, paste into a text file) into Netscape cookies.txt
format for curl (-b/-c) or wget (--load-cookies).

DevTools copies one cookie per line, tab-separated, in column order:
  Name, Value, Domain, Path, Expires/Max-Age, Size, HttpOnly, Secure,
  SameSite, Partition Key, ..., Priority
Only the first five columns plus HttpOnly/Secure are used. Missing
trailing columns are tolerated.

Usage:
  chrome2netscape.py cookies_pasted.txt > cookies.txt
  chrome2netscape.py < cookies_pasted.txt > cookies.txt
  chrome2netscape.py in.txt -o cookies.txt
"""

import argparse
import sys
from datetime import datetime, timezone

CHECK = {"✓", "✔", "true", "TRUE", "True", "yes", "1"}


def parse_expires(s: str) -> int:
    s = s.strip()
    if not s or s.lower() == "session":
        return 0  # session cookie
    # ISO 8601, e.g. 2026-12-31T23:59:59.000Z
    try:
        dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return int(dt.timestamp())
    except ValueError:
        pass
    # Already a unix timestamp?
    try:
        return int(float(s))
    except ValueError:
        pass
    # Older Chrome formats, e.g. "Thu, 31 Dec 2026 23:59:59 GMT"
    for fmt in ("%a, %d %b %Y %H:%M:%S %Z", "%a, %d-%b-%Y %H:%M:%S %Z"):
        try:
            return int(datetime.strptime(s, fmt).replace(tzinfo=timezone.utc).timestamp())
        except ValueError:
            pass
    print(f"warning: can't parse expiry {s!r}; treating as session cookie", file=sys.stderr)
    return 0


def convert(lines, httponly_prefix=True):
    out = ["# Netscape HTTP Cookie File", "# Converted from Chrome DevTools export", ""]
    count = 0
    names = []
    for lineno, raw in enumerate(lines, 1):
        line = raw.rstrip("\r\n")
        if not line.strip():
            continue
        f = line.split("\t")
        # Skip a header row if one got copied
        if f[0].strip().lower() == "name" and len(f) > 1 and f[1].strip().lower() == "value":
            continue
        if len(f) < 4:
            print(f"warning: line {lineno}: too few columns, skipped", file=sys.stderr)
            continue
        f += [""] * (8 - len(f))  # pad missing trailing columns

        name, value, domain, path = f[0], f[1], f[2].strip(), f[3].strip() or "/"
        expires = parse_expires(f[4])
        httponly = f[6].strip() in CHECK
        secure = f[7].strip() in CHECK

        # Domain cookies start with "." and apply to subdomains;
        # host-only cookies have no leading dot.
        include_sub = "TRUE" if domain.startswith(".") else "FALSE"
        prefix = "#HttpOnly_" if (httponly and httponly_prefix) else ""
        names.append(name)

        # WordPress auth cookie values are "user|expiry|token|hmac", stored
        # URL-encoded (%7C). A literal "|" means DevTools' "Show URL-decoded"
        # box was ticked when copying, and the server will reject it.
        if "|" in value and "%7C" not in value:
            print(f"warning: cookie {name!r} looks URL-decoded (contains '|'). "
                  "Untick 'Show URL-decoded' in DevTools and copy again.", file=sys.stderr)

        out.append("\t".join([
            prefix + domain,
            include_sub,
            path,
            "TRUE" if secure else "FALSE",
            str(expires),
            name,
            value,
        ]))
        count += 1
    print(f"converted {count} cookie(s)", file=sys.stderr)
    if any(n.startswith("wordpress_") for n in names) and not any(
            n.startswith("wordpress_logged_in_") for n in names):
        print("warning: WordPress cookies found but no wordpress_logged_in_* cookie; "
              "you probably weren't logged in when you copied them.", file=sys.stderr)
    return "\n".join(out) + "\n"


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("input", nargs="?", help="pasted DevTools cookies (default: stdin)")
    ap.add_argument("-o", "--output", help="output file (default: stdout)")
    ap.add_argument("--wget", action="store_true",
                    help="omit the #HttpOnly_ prefix (older wget treats those lines as "
                         "comments and silently drops login cookies)")
    a = ap.parse_args()

    if a.input:
        with open(a.input, encoding="utf-8") as fh:
            lines = fh.readlines()
    else:
        lines = sys.stdin.readlines()

    result = convert(lines, httponly_prefix=not a.wget)
    if a.output:
        with open(a.output, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(result)
    else:
        sys.stdout.write(result)


if __name__ == "__main__":
    main()
